import { useState } from "react";
import CoursePage from "./pages/CoursePage";
import AssessmentPage from "./pages/AssessmentPage";
import VideoPage from "./pages/VideoPage";

function App() {
  const [stage, setStage] = useState("course"); // "course" | "assessment" | "video"
  const [course, setCourse] = useState(null);
  const [questions, setQuestions] = useState(null);
  const [result, setResult] = useState(null);

  if (stage === "assessment") {
    return (
      <AssessmentPage
        questions={questions}
        course={course}
        setResult={setResult}
        setStage={setStage}
      />
    );
  }

  if (stage === "video") {
    return <VideoPage course={course} />;
  }

  // stage === "course"
  return (
    <CoursePage
      setCourse={setCourse}
      setQuestions={setQuestions}
      setStage={setStage}
    />
  );
}

export default App;
